# Fix: count comp size purely from the m mask (non-bg) — each component spans a mix of colors, so we can't attribute to one color easily. Instead, find connected components of a specific color using 4-adjacency restricted to same color.
def color_comps(g,col,bg):
    H,W=g.shape; comps=[]
    seen=[[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if g[i][j]==col and not seen[i][j]:
                stack=[(i,j)]; seen[i][j]=True; size=0
                while stack:
                    a,b=stack.pop(); size+=1
                    for da,db in [(-1,0),(1,0),(0,-1),(0,1)]:
